INSERT INTO `mst_inco_terms` (`id`, `incot_code`, `incot_name`, `incot_desc`) VALUES
(1, 'EXW', 'Ex Works', 'Seller makes goods available at their premises. Buyer handles everything else (transport, export, risk).\r\nUse EXW if you\'re the buyer and want full control.\r\nAvoid EXW for international exports (as a seller)\r\nBuyer handles export clearance, which can cause legal issues in many countries.'),
(2, 'FCA', 'Free Carrier', 'Seller delivers goods to a carrier chosen by the buyer at a named place.\r\nUse FCA/CIP for modern multimodal shipping\r\n\r\nUse FCA instead of FOB for containers\r\nFOB is technically for bulk cargo; FCA is safer and more modern for container shipments.'),
(3, 'CPT', 'Carriage Paid To', 'Seller pays transport to destination, but risk transfers earlier when goods are handed to the carrier.'),
(4, 'CIP', 'Carriage and Insurance Paid To', 'Same as CPT, but seller also provides insurance.\r\nUse FCA/CIP for modern multimodal shipping'),
(5, 'DAP', 'Delivered at Place', 'Seller delivers goods ready for unloading at destination. Buyer handles import duties.'),
(6, 'DPU', 'Delivered at Place Unloaded', 'Seller delivers and unloads goods at destination'),
(7, 'DDP', 'Delivered Duty Paid', 'Seller handles everything, including import duties and taxes—maximum responsibility for seller.\r\nUse DDP if you want a “door-to-door, hassle-free” experience\r\n\r\nUse DDP carefully\r\nSounds convenient, but seller must handle import taxes, customs, and local rules—can be risky if unfamiliar.'),
(8, 'FAS', 'Free Alongside Ship', 'Seller delivers goods alongside the ship at the port.'),
(9, 'FOB', 'Free On Board', 'Seller loads goods onto the ship; risk transfers once onboard.\r\nUse FOB/CIF commonly for sea freight.\r\n\r\nFOB is best when buyer controls shipping line.\r\nGood if you want to choose your own freight forwarder.'),
(10, 'CFR', 'Cost and Freight', 'Seller pays for transport to destination port, but risk transfers once goods are onboard.'),
(11, 'CIF', 'Cost, Insurance and Freight', 'Same as CFR, but seller also provides insurance.\r\nUse FOB/CIF commonly for sea freight');
