INSERT INTO `mst_tsc_termscond` (`id`, `termscond_shortdesc`, `termscond_text`, `termscondnnego_text`, `rtag`) VALUES
(3, 'Free Form with refusal to have handle poorly ', '1. Terms\n2.\n3.\n4. \n5.\n6.\n7.\n8.\n9.\n10. Right to Refuse: We reserve the right to refuse cargo that is poorly packed or poses a risk to other shipments in the container.', 'NON-NEGO', 'Y'),
(4, 'Free Form with Storage', '1. Terms\n2.\n3.\n4. \n5.\n6.\n7.\n8.\n9.\n10. Charges: Storage charges will accrue immediately upon the expiry of free time and must be paid before the release of goods.', '.', 'N'),
(5, 'Payment Details Only', 'Please pay in cash or manager\'s check to Larga International Logistics Inc.\nPayment beyond due is subject to 2% interest per month plus legal cost in \ncase of judicial proceedings.', 'LARGA\'s BANK DETAILS:\nBank Name: BDO Unibank\nBranch: BDO Mambog IV\nAccount Name: Larga Internal Logistics Inc.\nAccount Number: 000-560-300-263', 'Y'),
(6, 'Terms and Receipt Billed to Client', 'All receipted receipt are subject to liquidation and billed to client.\nQuotation Validity until December 31, 2026\nAbove rates are based on provided detail cargo only.\nTerms of payment is 15 days\nDuties and Taxes on Consigneed Account', 'Please pay in cash or manager\'s check to Larga International Logistics Inc.\nPayment beyond due is subject to 2% interest per month plus legal cost in case of judicial proceedings.\nLARGA\'s BANK DETAILS:\nAccount Name: Larga Internal Logistics Inc.\nAccount Number: 000-560-300-263', 'Y'),
(7, '', 'SAMPLE', 'SAMPLE', 'N');
