(1, '', 'TEST-USER', 'SYSINS', '2026-09-17 06:18:12', '', '', '', '', '', '', 'You have an error in your SQL syntax; check the manual that corresponds to your MariaDB server version for the right syntax to use near \'SEA\'  and  dd.`service_mvname` = \'IMPORT\'   \n        ) oa\' at line 29\r\nerror code: 1064\r\n/var/webapps/largasys/app/Models\r\nURI: /largasys/index.php/myfwd\r\nFile: /var/webapps/largasys/app/Models/MyCRMSales_Model.php\r\nLine Number: 366\r\n\n		select count(*) __nrecs from (SELECT aa.*,\n		(case when aa.`status` = \'APPRVD\' then \'Approved\'\n		when aa.`status` = \'DAPPRVD\' then \'Disapproved\' \n		when aa.`status` = \'CANCELLED\' then \'Cancelled\' \n		when aa.`status` = \'FAPPRVL\' then \'For Approval\' \n		when aa.`status` = \'POSTED\' then \'Posted\'\n		else \'Open\' end) mrecstat,\n        bb.`sysctrlno` `bkslpno`,\n		cc.`mot_desc`,\n		dd.`service_desc`,\n		ee.`name` `commodity_detl`,\n		bb.`sysctrlno` `bkslprefno`,\n		bb.shipper,\n		bb.shipper_addr,\n		bb.client,\n		bb.client_addr,\n		CONCAT(bb.`country_of_destination`,\' \',bb.`port_of_destination`) destination,\n		concat(bb.`origin_country`,\' \',bb.`port_of_origin`) origin,       \n		bb.agent,\n		bb.muser `mesales`,\n		bb.muser_apprvd `muser_apprvd_bkslip`,\n		bb.mdate_apprvd `mdate_apprvd_bkslip`,\n		cc.`mot_code` mmot,\n		dd.`service_mvname` mtcm \n        FROM ERPLogisticDev.`trx_qta_hd` aa  join ERPLogisticDev.`trx_bookslip_hd` bb on(aa.`bkslp_hd_id` = bb.id) \n        join ERPLogisticDev.`mst_mot` cc on(bb.`mode_of_shipm_id` = cc.id)\n        join ERPLogisticDev.`mst_services` dd on(bb.`type_of_service_id` = dd.recid) \n        join ERPLogisticDev.`mst_commodity` ee on(bb.`commodity_id` = ee.recid)\n		 where  bb.status = \'BOOKED and  cc.`mot_code` = \'SEA\'  and  dd.`service_mvname` = \'IMPORT\'   \n        ) oa\n		', '', '110.235.130.239', ''),
