(5, '', 'TEST-USER', 'SYSINS', '2026-09-21 06:36:00', '', '', '', '', '', '', 'You have an error in your SQL syntax; check the manual that corresponds to your MariaDB server version for the right syntax to use near \'z   \n        ) oa\' at line 21\r\nerror code: 1064\r\n/var/webapps/largasys/app/Models\r\nURI: /largasys/index.php/mytrxtemplbill\r\nFile: /var/webapps/largasys/app/Models/MyTrxBillTemplate_Model.php\r\nLine Number: 165\r\n\n		select count(*) __nrecs from (SELECT aa.*,\n		CONCAT(`country_of_destination`,\' \',`port_of_destination`) destination,\n		concat(`origin_country`,\' \',`port_of_origin`) origin,          \n		CONCAT(`country_of_destination`,\' \',`port_of_destination`) medestination,\n		concat(`origin_country`,\' \',`port_of_origin`) meorigin,\n		(case when aa.`status` = \'APPRVD\' then \'Approved\'\n		when aa.`status` = \'DAPPRVD\' then \'Disapproved\' \n		when aa.`status` = \'CANCELLED\' then \'Cancelled\' \n		when aa.`status` = \'FAPPRVL\' then \'For Approval\' \n		when aa.`status` = \'FCORR\' then \'For Correction\' \n		when aa.`status` = \'POSTED\' then \'Posted\'\n		else \'Open\' end) mrecstat,\n		  bb.`name` `mecommodity`,\n		  cc.`TYPE_DESC` `mecommodity_type`,\n		  sv.`service_desc`,\n		(select `ORGZN_NAME` from ERPLogisticDev.`mst_orgzn` where `recid` = aa.`sales_acct_id` limit 1) salesaname,\n		ifnull((select `desc` from ERPLogisticDev.`mst_bkslp_status` where `id` = aa.`rtag_id` limit 1),\'OPEN\') mertagstat \n        FROM ERPLogisticDev.`trx_billtmpl_slip_hd` aa join ERPLogisticDev.`mst_services` sv on(aa.`type_of_service_id` = sv.recid) \n		 join ERPLogisticDev.`mst_commodity` bb on(aa.commodity_id = bb.recid) \n		 join ERPLogisticDev.`mst_commodity_type` cc on(aa.commodity_type_id = cc.recid) \n		 where  aa.`orgzn_client_id` = 2226  and  aa.`momrtag` = 1 z   \n        ) oa\n		', '', '49.144.83.201', ''),
(6, '', 'TEST-USER', 'SYSINS', '2026-09-21 06:39:44', '', '', '', '', '', '', 'You have an error in your SQL syntax; check the manual that corresponds to your MariaDB server version for the right syntax to use near \'z   \n        ) oa\' at line 21\r\nerror code: 1064\r\n/var/webapps/largasys/app/Models\r\nURI: /largasys/index.php/mytrxtemplbill\r\nFile: /var/webapps/largasys/app/Models/MyTrxBillTemplate_Model.php\r\nLine Number: 165\r\n\n		select count(*) __nrecs from (SELECT aa.*,\n		CONCAT(`country_of_destination`,\' \',`port_of_destination`) destination,\n		concat(`origin_country`,\' \',`port_of_origin`) origin,          \n		CONCAT(`country_of_destination`,\' \',`port_of_destination`) medestination,\n		concat(`origin_country`,\' \',`port_of_origin`) meorigin,\n		(case when aa.`status` = \'APPRVD\' then \'Approved\'\n		when aa.`status` = \'DAPPRVD\' then \'Disapproved\' \n		when aa.`status` = \'CANCELLED\' then \'Cancelled\' \n		when aa.`status` = \'FAPPRVL\' then \'For Approval\' \n		when aa.`status` = \'FCORR\' then \'For Correction\' \n		when aa.`status` = \'POSTED\' then \'Posted\'\n		else \'Open\' end) mrecstat,\n		  bb.`name` `mecommodity`,\n		  cc.`TYPE_DESC` `mecommodity_type`,\n		  sv.`service_desc`,\n		(select `ORGZN_NAME` from ERPLogisticDev.`mst_orgzn` where `recid` = aa.`sales_acct_id` limit 1) salesaname,\n		ifnull((select `desc` from ERPLogisticDev.`mst_bkslp_status` where `id` = aa.`rtag_id` limit 1),\'OPEN\') mertagstat \n        FROM ERPLogisticDev.`trx_billtmpl_slip_hd` aa join ERPLogisticDev.`mst_services` sv on(aa.`type_of_service_id` = sv.recid) \n		 join ERPLogisticDev.`mst_commodity` bb on(aa.commodity_id = bb.recid) \n		 join ERPLogisticDev.`mst_commodity_type` cc on(aa.commodity_type_id = cc.recid) \n		 where  aa.`orgzn_client_id` = 2226  and  aa.`momrtag` = 1 z   \n        ) oa\n		', '', '49.144.83.201', ''),
(7, '', 'TEST-USER', 'SYSINS', '2026-09-21 19:50:50', '', '', '', '', '', '', 'You have an error in your SQL syntax; check the manual that corresponds to your MariaDB server version for the right syntax to use near \'sum(`total_package`) ntot_package,\n	sum(`gross_weight`) ntot_gw,\n	sum(`measur...\' at line 1\r\nerror code: 1064\r\n/var/webapps/largasys/app/Models\r\nURI: /largasys/index.php/myfwd\r\nFile: /var/webapps/largasys/app/Views/myfwd/conso/myfwd-conso-sea-import-mbl-form-wdata.php\r\nLine Number: 157\r\nselect count(*) mehblcnt sum(`total_package`) ntot_package,\n	sum(`gross_weight`) ntot_gw,\n	sum(`measurement`) ntot_meas from ERPLogisticDev.trx_forwarding_sea_manifest_hbl where `hd_id` = ?', '', '149.30.129.12', ''),
(8, '', 'TEST-USER', 'SYSINS', '2026-09-21 20:15:03', '', '', '', '', '', '', 'Unknown column \'ist.desctiption\' in \'SELECT\'\r\nerror code: 1054\r\n/var/webapps/largasys/app/Models\r\nURI: /largasys/index.php/myfwd\r\nFile: /var/webapps/largasys/app/Views/myfwd/trx-statuses-update-remk-form.php\r\nLine Number: 65\r\nselect hs.`id`,\nhs.`rtagstat_id`,\nhs.`hd_id`,\nhs.`chkdate`,\nhs.`remk`,\nhs.`mfile`,\nhs.`mofile`,\nhs.`mfilepath`,\nhs.`muser` `updated_by`,\nhs.`mdate`,\ndate_format(hs.`mdate`,\'%m/%d/%Y\') medate,\ndate_format(hs.`mdate`,\'%h:%i:%s %p\') metimeampm,\nist.desctiption `internal_stat` from ERPLogisticDev.`trx_fwd_statuses` st \njoin ERPLogisticDev.`trx_fwd_statuses_remk_update` hs on(hs.`hd_id` = st.`recid`) \njoin ERPLogisticDev.`mst_universal_status` ist on(hs.`rtagstat_id` = ist.`recid`) \nwhere st.`hbl_id` = ? and st.`servtype_id` = ? and \nst.`cargomv_id` = ? order by `mdate` desc  limit 1', '', '149.30.129.12', '');
