INSERT INTO `sys_ua_sqllogs` (`recid`, `LOG_METKN`, `LOG_USER`, `LOG_MODULE`, `LOG_DATE`, `LOG_SQL`, `LOG_IPADDR`, `LOG_PRNT`) VALUES
(1, 'f35e5mcrfgz0b8w6vpp4', 'TEST-USER', 'SYSMENU_MAPPING', '2026-09-17 16:15:52', 'SELECT `recid`,`MSA_SYS`,`MSA_SYS_NAME`,`MSA_MODULE`,`MSA_MODULE_NAME`,`MSA_SMODULE`,`MSA_SMODULE_NAME`,`MSA_ENCDTE`,`MSA_MRK`,\n		`MSA_GROUP`,`MSA_URI_MAPPING`,if(`MSA_MRK` = \'Y\',\'YES\',\'NO\') `MEMNUACTIVATED`,`MSA_INDEX`,`MSA_STATUS_DISPLAY`, `MSA_APPEAR_STATUS_SETUP`,\n		`MSA_APPEAR_STATUS_SETUP_HDR`,`MSA_APPEAR_STATUS_SETUP_DTL` FROM ERPLogisticDev.`mod_sec_menus` ', '49.144.83.201', ''),
(2, 'lsbuho7iqiankpv28ghh', 'TEST-USER', 'SYSMENU_MAPPING', '2026-09-17 16:15:58', 'SELECT `recid`,`MSA_SYS`,`MSA_SYS_NAME`,`MSA_MODULE`,`MSA_MODULE_NAME`,`MSA_SMODULE`,`MSA_SMODULE_NAME`,`MSA_ENCDTE`,`MSA_MRK`,\n		`MSA_GROUP`,`MSA_URI_MAPPING`,if(`MSA_MRK` = \'Y\',\'YES\',\'NO\') `MEMNUACTIVATED`,`MSA_INDEX`,`MSA_STATUS_DISPLAY`, `MSA_APPEAR_STATUS_SETUP`,\n		`MSA_APPEAR_STATUS_SETUP_HDR`,`MSA_APPEAR_STATUS_SETUP_DTL` FROM ERPLogisticDev.`mod_sec_menus` ', '49.144.83.201', ''),
(3, 't1v8f6ajuobzes9rf6dq', 'TEST-USER', 'SYSMENU_MAPPING', '2026-09-17 16:16:16', 'SELECT `recid`,`MSA_SYS`,`MSA_SYS_NAME`,`MSA_MODULE`,`MSA_MODULE_NAME`,`MSA_SMODULE`,`MSA_SMODULE_NAME`,`MSA_ENCDTE`,`MSA_MRK`,\n		`MSA_GROUP`,`MSA_URI_MAPPING`,if(`MSA_MRK` = \'Y\',\'YES\',\'NO\') `MEMNUACTIVATED`,`MSA_INDEX`,`MSA_STATUS_DISPLAY`, `MSA_APPEAR_STATUS_SETUP`,\n		`MSA_APPEAR_STATUS_SETUP_HDR`,`MSA_APPEAR_STATUS_SETUP_DTL` FROM ERPLogisticDev.`mod_sec_menus` ', '49.144.83.201', ''),
(4, 'avux9au8xcfhl9lfhf9u', 'TEST-USER', 'TSC_PRICING_DATAEXPORT', '2026-09-23 15:58:31', '\n		SELECT \n		bb.`tsc_code` `Service Code`,\n		bb.`tsc_desc` `Service Name`,\n		bb.`tsc_rtag` `Activated`,\n		dd.`tmsc_desc` `Charges Type`,\n		cc.`service_desc` `Cargo Movement`,\n		ee.`CGT_DESC` `Cargo Type`, \n		ff.`basis_desc` `Basic`,\n		ifnull(mcurr.`CURR_CODE`,\'\') `Currrency`,\n		aa.`tsc_cost` `Cost`,\n		aa.`tsc_defminmarkup_perc` `Min Markup (%)`,\n		aa.`tsc_defmaxmarkup_perc` `Max Markup (%)`,\n		aa.`tsc_markup_percent` `Markup (%)`,\n		if(aa.tsc_cost > 0,aa.tsc_cost + if(aa.`tsc_markup_percent` > 0,(aa.tsc_cost * (aa.`tsc_markup_percent` / 100)),0),aa.tsc_cost) `Selling` \n		FROM ERPLogisticDev.`mst_tsc_pricing_matrix` aa \n		join ERPLogisticDev.`mst_trade_service_charges` bb on(aa.`tsc_id` = bb.id) \n		join ERPLogisticDev.`mst_services` cc on(aa.tsc_cargomv_id = cc.recid) \n		join ERPLogisticDev.`mst_trade_service_charges_type` dd on(dd.id = aa.tsc_charge_type_id) \n		join ERPLogisticDev.`mst_cargo_type` ee on(ee.recid = aa.tsc_cargotyp_id) \n		join ERPLogisticDev.`mst_basis` ff on(ff.recid = aa.tsc_chargebasis_id) \n		left join ERPLogisticDev.`mst_currency` mcurr on(mcurr.recid = aa.tsc_curr) \n		where aa.`isupdated` = \'Y\' ORDER BY bb.`tsc_desc`,dd.`tmsc_desc`,cc.`service_desc`,ee.`CGT_DESC` \n		', '110.235.130.239', ''),
(5, 'y3o4mhwuik3jys8n6vgp', 'TEST-USER', 'TSC_PRICING_DATAEXPORT', '2026-09-29 08:23:03', '\n		SELECT \n		bb.`tsc_code` `Service Code`,\n		bb.`tsc_desc` `Service Name`,\n		bb.`tsc_rtag` `Activated`,\n		dd.`tmsc_desc` `Charges Type`,\n		cc.`service_desc` `Cargo Movement`,\n		ee.`CGT_DESC` `Cargo Type`, \n		ff.`basis_desc` `Basic`,\n		ifnull(mcurr.`CURR_CODE`,\'\') `Currrency`,\n		aa.`tsc_cost` `Cost`,\n		aa.`tsc_defminmarkup_perc` `Min Markup (%)`,\n		aa.`tsc_defmaxmarkup_perc` `Max Markup (%)`,\n		aa.`tsc_markup_percent` `Markup (%)`,\n		if(aa.tsc_cost > 0,aa.tsc_cost + if(aa.`tsc_markup_percent` > 0,(aa.tsc_cost * (aa.`tsc_markup_percent` / 100)),0),aa.tsc_cost) `Selling` \n		FROM ERPLogisticDev.`mst_tsc_pricing_matrix` aa \n		join ERPLogisticDev.`mst_trade_service_charges` bb on(aa.`tsc_id` = bb.id) \n		join ERPLogisticDev.`mst_services` cc on(aa.tsc_cargomv_id = cc.recid) \n		join ERPLogisticDev.`mst_trade_service_charges_type` dd on(dd.id = aa.tsc_charge_type_id) \n		join ERPLogisticDev.`mst_cargo_type` ee on(ee.recid = aa.tsc_cargotyp_id) \n		join ERPLogisticDev.`mst_basis` ff on(ff.recid = aa.tsc_chargebasis_id) \n		left join ERPLogisticDev.`mst_currency` mcurr on(mcurr.recid = aa.tsc_curr) \n		where aa.`isupdated` = \'Y\' ORDER BY bb.`tsc_desc`,dd.`tmsc_desc`,cc.`service_desc`,ee.`CGT_DESC` \n		', '49.144.83.201', ''),
